const PARENT_RESOURCES=[{"title": "Family Faith Without Pressure", "summary": "Create regular opportunities for Bible reading, conversation and prayer without forcing children or teens to perform spirituality publicly."}, {"title": "Listening to Teen Questions", "summary": "Treat difficult questions as learning opportunities. Listen fully, admit when you do not know an answer, and study together."}, {"title": "Correcting With Dignity", "summary": "Set boundaries clearly, explain consequences calmly, and avoid humiliation, public shaming or threatening spiritual language."}, {"title": "Building a Family Prayer Rhythm", "summary": "Keep family prayer simple and consistent. Short, sincere prayer is better than a routine that becomes exhausting."}, {"title": "Digital Wisdom at Home", "summary": "Create shared expectations around screen time, privacy, online kindness and content without turning every digital conversation into punishment."}, {"title": "Helping Children Use the Bible", "summary": "Teach how to find books, chapters and verses; let children participate in reading at an age-appropriate level."}, {"title": "Faith During Difficult Weeks", "summary": "When schedules are hard, shorten the routine instead of abandoning it completely. A five-minute conversation can still be meaningful."}, {"title": "Family Service", "summary": "Choose practical, safe service activities appropriate to the family's ages, abilities and church safeguarding guidance."}, {"title": "Celebrating Progress", "summary": "Notice growth in honesty, patience, responsibility and compassion rather than turning faith into a points competition."}, {"title": "When Family Members Disagree", "summary": "Allow respectful disagreement, return to Scripture carefully, and avoid using authority to silence sincere questions."}, {"title": "Preparing for Sunday", "summary": "Check the coming lesson, pray for teachers, prepare Bibles or notebooks, and arrive ready rather than rushed where possible."}, {"title": "Following Up After Sunday School", "summary": "Ask what the learner remembers and what questions remain. Avoid turning the conversation into a test."}];
const AGE_STAGES=[{"id": "early", "label": "Early Years", "range": "Ages 3–5", "icon": "🧸", "description": "Short, concrete, visual and repetition-friendly faith moments.", "tips": ["Keep family moments around 3–7 minutes.", "Use pictures, movement and simple retelling.", "Repeat one key truth more than once.", "Offer listening as a valid form of participation."]}, {"id": "kids", "label": "Kids", "range": "Ages 6–9", "icon": "🎨", "description": "Story, discovery, questions, memory and practical action.", "tips": ["Let children find Bible references with help.", "Use drawing, sequencing and short questions.", "Connect one truth to school, friendship or home.", "Praise effort and growth rather than performance."]}, {"id": "preteen", "label": "Preteens", "range": "Ages 10–12", "icon": "🧭", "description": "Growing independence, deeper questions and responsibility.", "tips": ["Invite questions without turning every answer into a lecture.", "Give meaningful family responsibilities.", "Connect Bible truth with friendships and digital choices.", "Let them help lead a short family moment."]}, {"id": "teen", "label": "Teens", "range": "Ages 13–17", "icon": "💬", "description": "Conversation, identity, wisdom, questions and real-life application.", "tips": ["Listen fully before responding.", "Allow respectful disagreement and honest questions.", "Discuss faith, school, friendships and digital life without forcing disclosure.", "Give teens meaningful ways to serve using their strengths."]}, {"id": "mixed", "label": "Whole Family", "range": "Mixed ages", "icon": "👨‍👩‍👧‍👦", "description": "One shared truth with different participation options.", "tips": ["Ask simpler and deeper versions of the same question.", "Let younger children draw while older children discuss.", "Keep the main idea the same for everyone.", "End with one shared family action."]}];
const EVERYDAY_MOMENTS=[{"id": "morning", "icon": "🌅", "title": "Morning Cue", "summary": "Start small before the day becomes busy.", "pattern": "One truth + one sentence prayer", "example": "What truth from this week's lesson do we want to carry into today?"}, {"id": "meal", "icon": "🍽️", "title": "Meal Cue", "summary": "Use a normal meal as a natural conversation point.", "pattern": "One question + listen", "example": "Where did you notice kindness, courage, wisdom or patience today?"}, {"id": "move", "icon": "🚶", "title": "On-the-Go Cue", "summary": "Talk during a walk, car ride or routine journey.", "pattern": "One observation + one connection", "example": "What did you see today that connects with our Bible lesson?"}, {"id": "evening", "icon": "🌙", "title": "Evening Cue", "summary": "Close the day with reflection rather than a long programme.", "pattern": "Thank + ask + pray", "example": "What are we thankful for, and what do we want God's help with tomorrow?"}];
const PARENT_TIPS=[{"month": "January", "title": "Start Small, Stay Consistent", "tip": "Choose a short family rhythm you can repeat. Five intentional minutes done regularly is more useful than a long routine that disappears after two weeks."}, {"month": "February", "title": "Ask Before You Explain", "tip": "When a child or teen asks a faith question, first ask what they already think. Listening helps you answer the real question rather than the one you assumed."}, {"month": "March", "title": "Connect Faith to Ordinary Life", "tip": "Use school, friendship, chores, decisions, media and family relationships as natural places to discuss wisdom, honesty, courage and kindness."}, {"month": "April", "title": "Correct With Dignity", "tip": "State the boundary, explain the reason, use fair consequences and avoid humiliation. Correction should aim at learning and restoration."}, {"month": "May", "title": "Let Questions Be Welcome", "tip": "A difficult question is not automatically rebellion. Say when you need time to study, then return to the conversation later."}, {"month": "June", "title": "Use Everyday Moments", "tip": "Faith conversations do not need a formal table every time. Use meals, walks, errands and bedtime as natural moments for short cues."}, {"month": "July", "title": "Serve Together", "tip": "Choose safe service your family can do together. Service helps turn Bible learning into compassion and responsibility."}, {"month": "August", "title": "Prepare for Sunday", "tip": "Look at the coming topic, pray for teachers and arrive with one question your family wants to explore."}, {"month": "September", "title": "Notice Character Growth", "tip": "Celebrate growth in patience, honesty, responsibility, courage and kindness—not only Bible knowledge or public performance."}, {"month": "October", "title": "Talk About Digital Wisdom", "tip": "Create shared expectations around devices, privacy, kindness and attention. Adults should model the same habits they ask young people to practise."}, {"month": "November", "title": "Practise Specific Gratitude", "tip": "Move beyond 'thank You for everything.' Name ordinary people, opportunities, help and provision you might otherwise overlook."}, {"month": "December", "title": "Review Before You Add More", "tip": "Ask what family faith habits worked this year, what felt forced, and what one rhythm you want to carry into the next year."}];
