const QUESTION_LAB=[{"id": "q1", "category": "Bible", "question": "Why should we read the Bible?", "summary": "Christians read Scripture to understand the biblical story, God’s character, Jesus, and faithful living. Context matters because verses belong to paragraphs, books, and the larger story.", "explore": ["What kind of books are in the Bible?", "Why does context matter?", "How can reading lead to wise action?"], "references": ["2 Timothy 3:16–17", "Psalm 119:105", "Luke 24:27"]}, {"id": "q2", "category": "Prayer", "question": "Why pray if God already knows what we need?", "summary": "Prayer is more than giving information. It includes worship, dependence, confession, gratitude, lament, request, and relationship.", "explore": ["How did Jesus teach prayer?", "What is the difference between asking and demanding?", "How can families discuss unanswered prayer honestly?"], "references": ["Matthew 6:8–13", "Philippians 4:6–7", "Psalm 13"]}, {"id": "q3", "category": "Jesus", "question": "Why is Jesus central to Christianity?", "summary": "Christian faith centres on Jesus—His life, teaching, death, resurrection, lordship, and the claim that God’s saving work is revealed decisively through Him.", "explore": ["What do the Gospels say Jesus did?", "Why does the resurrection matter?", "How did the early church speak about Jesus?"], "references": ["John 1:14", "1 Corinthians 15:3–4", "Colossians 1:15–20"]}, {"id": "q4", "category": "Suffering", "question": "Why do painful things happen?", "summary": "The Bible does not reduce suffering to one simple explanation. It describes consequences, injustice, a broken world, persecution, natural suffering, and mysteries people do not fully understand, while also showing God meeting people in pain.", "explore": ["How do the Psalms express pain?", "What can we learn from Job without oversimplifying?", "How can families support someone who is hurting?"], "references": ["Psalm 34:18", "Romans 8:22–25", "John 11:33–36"]}, {"id": "q5", "category": "Faith", "question": "Does having faith mean never having questions?", "summary": "No. Scripture includes people who ask, doubt, lament, seek evidence, and grow. Honest questions can be explored thoughtfully rather than punished.", "explore": ["What did Thomas ask?", "What does Mark 9:24 show?", "How can we question respectfully?"], "references": ["John 20:24–29", "Mark 9:24", "Acts 17:11"]}, {"id": "q6", "category": "Creation", "question": "What does it mean that humans are made in God’s image?", "summary": "Genesis gives human beings unique dignity and responsibility under God. Christians commonly connect this with human worth, relationship, moral responsibility, and stewardship.", "explore": ["How should this affect how we treat people?", "What responsibilities appear in Genesis 1–2?", "Why does dignity include people unlike us?"], "references": ["Genesis 1:26–28", "James 3:9–10"]}, {"id": "q7", "category": "Forgiveness", "question": "Does forgiveness mean pretending nothing happened?", "summary": "No. Forgiveness rejects personal revenge, but truth, wisdom, boundaries, justice, safety, and rebuilding trust still matter.", "explore": ["How did Joseph respond to his brothers?", "What is the difference between forgiveness and immediate trust?", "When should a trusted adult or leader be involved?"], "references": ["Genesis 45", "Romans 12:17–21", "Ephesians 4:32"]}, {"id": "q8", "category": "Church", "question": "Why does Christian community matter?", "summary": "The New Testament describes faith as communal as well as personal. Believers learn, worship, serve, pray, give, and encourage one another in community.", "explore": ["What practices appear in Acts 2?", "Why can community be difficult?", "How should damaged trust be handled wisely?"], "references": ["Acts 2:42–47", "Hebrews 10:24–25", "1 Corinthians 12:12–27"]}, {"id": "q9", "category": "Identity", "question": "Where should our identity come from?", "summary": "Christian teaching calls people to ground identity in relationship to God rather than making popularity, achievement, appearance, possessions, or online attention ultimate.", "explore": ["How can achievement become an unhealthy identity anchor?", "What does belonging to Christ mean?", "How should identity shape choices?"], "references": ["Galatians 3:26–28", "Ephesians 2:10", "Colossians 3:1–4"]}, {"id": "q10", "category": "Wisdom", "question": "How do we make wise decisions when the Bible does not name our exact situation?", "summary": "Families can combine biblical principles, prayer, trustworthy counsel, facts, consequences, character, and patience rather than searching for one isolated proof-text.", "explore": ["What values are at stake?", "What are the likely consequences?", "Who is a trustworthy adviser?"], "references": ["Proverbs 11:14", "James 1:5", "Romans 12:2"]}, {"id": "q11", "category": "Science & Faith", "question": "Can Christians value science and also have faith?", "summary": "Many Christians see scientific study as investigation of the natural world and faith as addressing theological questions of God, meaning, purpose, worship, and moral responsibility. Christians hold different interpretations on some origins questions.", "explore": ["What questions does science investigate well?", "Which questions are philosophical or theological?", "How can disagreements be discussed respectfully?"], "references": ["Psalm 19:1", "Genesis 1:1", "Proverbs 25:2"]}, {"id": "q12", "category": "Other Religions", "question": "How should Christians treat people of other religions?", "summary": "Christian teaching calls believers to love neighbours, treat people with dignity, speak truthfully, and avoid hatred or coercion. Disagreement does not remove another person’s human worth.", "explore": ["How did Jesus define neighbour-love?", "What does respectful witness look like?", "How can people disagree without hostility?"], "references": ["Luke 10:25–37", "1 Peter 3:15–16", "Romans 12:18"]}, {"id": "q13", "category": "Digital Life", "question": "How can faith shape social media and gaming?", "summary": "Digital spaces are still places where character matters. Wisdom includes attention, privacy, honesty, kindness, self-control, healthy limits, and asking trusted adults for help when something feels unsafe.", "explore": ["Would I say this face to face?", "What information should stay private?", "Does this habit strengthen or weaken self-control?"], "references": ["Philippians 4:8", "Galatians 5:22–23", "Ephesians 4:29"]}, {"id": "q14", "category": "Money", "question": "What does the Bible teach about money?", "summary": "Scripture speaks about work, generosity, contentment, justice, planning, avoiding greed, and using resources responsibly.", "explore": ["What is the difference between money and love of money?", "What does generosity look like for our family?", "How can planning reduce careless spending?"], "references": ["1 Timothy 6:6–10", "Proverbs 21:5", "2 Corinthians 9:7"]}, {"id": "q15", "category": "Friendship", "question": "What makes a healthy friendship?", "summary": "Healthy friendship includes honesty, loyalty, mutual respect, encouragement, appropriate boundaries, and freedom to say no to harmful pressure.", "explore": ["How did Jonathan treat David?", "What is peer pressure?", "How can a friend disagree respectfully?"], "references": ["1 Samuel 18–20", "Proverbs 17:17", "Proverbs 27:17"]}, {"id": "q16", "category": "Purpose", "question": "How do we discover purpose?", "summary": "Christian purpose begins broadly—loving God and neighbour, growing in character, serving faithfully, and using gifts responsibly. Specific vocation often becomes clearer through learning, service, counsel, and experience.", "explore": ["What abilities are developing?", "What needs do we notice?", "Which responsibilities are already in front of us?"], "references": ["Micah 6:8", "Ephesians 2:10", "1 Peter 4:10"]}, {"id": "q17", "category": "Holy Spirit", "question": "What does the Holy Spirit do?", "summary": "The New Testament describes the Holy Spirit as God’s presence empowering witness, producing Christlike character, guiding the church, giving gifts, and helping believers pray and live faithfully.", "explore": ["What happened at Pentecost?", "What is the fruit of the Spirit?", "How should spiritual gifts serve others?"], "references": ["Acts 1:8", "Galatians 5:22–23", "1 Corinthians 12:4–7"]}, {"id": "q18", "category": "Worship", "question": "Is worship only singing?", "summary": "Singing is one form of worship, but biblical worship also includes prayer, obedience, generosity, service, gratitude, justice, and offering everyday life to God.", "explore": ["How does Romans 12 describe worship?", "What is the link between worship and obedience?", "How can ordinary responsibilities honour God?"], "references": ["Romans 12:1", "Psalm 95:1–7", "Colossians 3:17"]}, {"id": "q19", "category": "Character", "question": "Can people really change?", "summary": "Christian faith takes both grace and formation seriously. Change often includes repentance, new habits, community, truth, and time rather than instant perfection.", "explore": ["How did Zacchaeus show change?", "What changed in Saul’s direction?", "Why do repeated habits matter?"], "references": ["Luke 19:1–10", "Acts 9", "Romans 12:2"]}, {"id": "q20", "category": "Family", "question": "What if our family faith routine is inconsistent?", "summary": "Begin again without guilt. Choose one small rhythm, make it realistic, and review what helps. Consistency grows through repeatable habits, not perfect weeks.", "explore": ["Which moment already exists in our schedule?", "What routine feels too complicated?", "What one practice could we repeat for four weeks?"], "references": ["Deuteronomy 6:6–7", "Galatians 6:9", "Zechariah 4:10"]}];
